We also want to introduce an auxiliary quantity
\begin{equation} G_z(u)=\displaystyle\sum\limits_{f\in\mathcal{M}} z^{\Omega(f)}u^{deg (f)}=\displaystyle\prod_{p\in\mathcal{P}}\left(1-zu^{deg(p)}\right)^{-1}.
\end{equation}

We do this job by introducing another function $F_z(u)$ via the Euler product
\begin{equation} F_z(u)=\displaystyle\prod\limits_{p\in\mathcal{P}}\left(1-zu^{deg(p)} \right)^{-1}\left(1-u^{deg(p)} \right)^z.
\end{equation}

Furthermore considering the Euler products in (\ref{l40}) and $(\ref{l55})$ we can connect $G_z(u)$ and $F_z(u)$ in the following way whenever $|u|<\min \big\{ |z|^{-1},q^{-\frac 12}\big\}$
\begin{equation} G_z(u)=\zeta(u)^zF_z(u).
\end{equation}

Let $|u|=r < q^{-1}$ (small green circle in Fig-\ref{A} above). Using Cauchy's integral formula on (\ref{l40}) we get for each fixed $z$ satisfying the hypothesis $|z|\leqslant q-\epsilon$,
\begin{equation} M_z(n)=\dfrac{1}{2\pi i}\displaystyle\int\limits_{|u|=r}G_z(u) \dfrac{du}{u^{n+1}}=\dfrac{1}{2\pi i}\displaystyle\int\limits_{|u|=r}\zeta(u)^zF_z(u) \dfrac{du}{u^{n+1}}.
\end{equation}

Now, we evaluate the main term using Lemma \ref{l3}
\begin{align}
\nonumber
F_z\left( \dfrac{1}{q}\right)\dfrac{1}{2\pi i}\displaystyle\int_{\mathcal{H}'}\zeta(u)^z\dfrac{du}{u^{n+1}} &= F_z\left( \dfrac{1}{q}\right)\dfrac{1}{2\pi i}\displaystyle\int_{\mathcal{H}'}\dfrac{1}{(1-qu)^z}\dfrac{du}{u^{n+1}}\\
\nonumber
&=F_z\left( \dfrac{1}{q}\right)\dfrac{q^n}{n}\dfrac{1}{2\pi i}\displaystyle\int_{\mathcal{H}}\dfrac{1}{\left(\dfrac{w}{n}\right)^{z}}\dfrac{-dw}{\left(1-\dfrac{w}{n} \right)^{n+1}}\\
\nonumber
&=F_z\left( \dfrac{1}{q}\right)q^n n^{z-1}\left( \dfrac{1}{\Gamma(z)}+O_{\epsilon}\left( \dfrac{1}{n}\right)\right).
\end{align}

We plan to recover $N(n,k)$ with another application of Cauchy's integral formula, 
\begin{equation} N(n,k)=\dfrac{1}{2\pi i}\displaystyle\int\limits_{|z|=\frac{k}{\log n}} M_z(n) \dfrac{dz}{z^{k+1}}.
\end{equation}

\begin{align}
\nonumber
\displaystyle\int\limits_{-\infty}^{\infty} \theta^2\exp\left( - \dfrac{k\theta^2}{5} \right)d\theta  &= \dfrac{5\sqrt{5}}{k^{\frac{3}{2}}}\displaystyle\int_{0}^{\infty}\sqrt{z}e^{-z}dz \qquad \left(z=\dfrac{k\theta^2}{5}\right)\\
\nonumber
&\ll k^{-\frac{3}{2}}. \qquad \left( \text{ since }\displaystyle\int_{0}^{\infty}\sqrt{z}e^{-z}dz \text{ is convergent} \right)
\end{align}

We determine the coefficient of $u^n$ in $\widetilde{{G}_z}(u)$ using Cauchy's integral formula and recover $\widetilde{{M}_z}(n)$ exactly as in the proof of Theorem \ref{l6}. We have that, if $|u|=r < q^{-1}$ (refer to the small green circle in the same Fig-\ref{Ax} below), then using Cauchy's residue formula on (\ref{l40}) gives
\begin{equation} \widetilde{M_z}(n)=\dfrac{1}{2\pi i}\displaystyle\int\limits_{|u|=r}\widetilde{G_z}(u) \dfrac{du}{u^{n+1}}=\dfrac{1}{2\pi i}\displaystyle\int\limits_{|u|=r}\zeta(u)^z\widetilde{F_z}(u) \dfrac{du}{u^{n+1}}.
\end{equation}

By Lemma \ref{l11} we have that
\begin{equation} N'(n+j-k,j)=\dfrac{q^{n+j-k}}{n+j-k}\Bigg \{Q_j(\log (n+j-k))+ O \left( \dfrac{(\log (n+j-k))^j}{j!(n+j-k)}\right) \Bigg \}.
\end{equation}

Thus from \eqref{nw} we arrive at
\begin{equation} N'(n+j-k,j)=q^{n+j-k}\left \{\dfrac{Q_j(\log (n+j-k))}{n+j-k}+ O \left( E_1\right)\right \}
\end{equation}

By mean value theorem one can pick $y\in (n-k,n+j-k)$ such that
$$D=jF'(y)=j\dfrac{Q_j'(\log y)-Q_j(\log y)}{y^2}=\dfrac{j}{y^2}Q_j'(\log y)-\dfrac{j}{y^2}Q_j(\log y)=F_1+F_2.$$
Therefore \eqref{nw1} implies
\begin{equation} N'(n+j-k,j)=q^{n+j-k}\left \{\frac{Q_j(\log (n-k))}{n-k}+ F_1+F_2+O \left( E_1\right)\right \}
\end{equation}
